 if(!data)return <div className="loading-page"><div className="logo-mark"><ShieldCheck size={26}/></div><h2>ASPHALES</h2><p>{error||'Preparing your workspace…'}</p>{error?<button className="btn primary" onClick={load}>Try again</button>:<span className="loader"/>}</div>;
 const s=data.state,d=s.deals.find(x=>x.id===selected),active=s.deals.filter(x=>!['Completed','Refunded'].includes(x.status)),funded=s.deals.filter(x=>x.funded&&!['Completed','Refunded'].includes(x.status)),review=s.deals.filter(x=>x.status==='In review'),totalEscrow=funded.reduce((n,x)=>n+x.amount,0),completed=s.deals.filter(x=>x.status==='Completed'),paid=completed.reduce((n,x)=>n+amounts(x).net,0),filtered=s.deals.filter(x=>(filter==='All deals'||x.status===filter)&&`${x.title} ${x.brand} ${x.creator} ${x.id}`.toLowerCase().includes(query.toLowerCase())),focus=review[0],registered=role==='Business'?s.settings.businessRegistered:role==='Creator'?s.settings.creatorRegistered:true;
 const money=d?amounts(d):null;
