async function watermark(file:File,dealId:string):Promise<Blob>{
 if(file.size>20*1024*1024)throw Error('Choose an image under 20 MB.');
 const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*ratio));canvas.height=Math.max(1,Math.round(bitmap.height*ratio));const ctx=canvas.getContext('2d');if(!ctx)throw Error('Image processing is not available.');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();ctx.save();ctx.translate(canvas.width/2,canvas.height/2);ctx.rotate(-Math.PI/7);ctx.font=`600 ${Math.max(15,canvas.width/30)}px Arial`;ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,0.63)';ctx.shadowColor='rgba(0,0,0,0.5)';ctx.shadowBlur=3;for(let y=-canvas.height;y<=canvas.height;y+=Math.max(70,canvas.height/4))for(let x=-canvas.width;x<=canvas.width;x+=Math.max(260,canvas.width*.8))ctx.fillText('ASPHALES · REVIEW COPY',x,y);ctx.restore();const bar=Math.max(27,canvas.height*.045);ctx.fillStyle='rgba(20,47,39,.86)';ctx.fillRect(0,canvas.height-bar,canvas.width,bar);ctx.fillStyle='#fff';ctx.font=`${Math.max(10,bar*.4)}px Arial`;ctx.fillText(dealId+' · Protected review preview',12,canvas.height-bar*.35);return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Could not watermark this image.')),'image/jpeg',.86));
}
